const format = (text: string, values: Record<string, string>) => text.replace(/\{(\w+)\}/g, (_, key: string) => values[key] ?? "");
export function buildDocumentContent(locale: Locale, title: string, category: string, fields: string[], kind: "form" | "checklist" | "planner", hasTable: boolean, policy: boolean) {
  const t = copy[locale];
  const specific = specificCopy[locale];
  const named = { title, category };
  const fieldNames = fields.slice(0, 8).join(locale === "ko" || locale === "ja" || locale === "zh" || locale === "zh-tw" ? " · " : ", ");
  const focusFields = fields.slice(0, 8).join(locale === "ko" || locale === "ja" || locale === "zh" || locale === "zh-tw" ? " · " : ", ");
  const more = fields.length > 8 ? (locale === "ko" ? ` 외 ${fields.length - 8}개` : locale === "ru" ? format(t.more ?? "", { count: String(fields.length - 8) }) : ` + ${fields.length - 8}`) : "";
  const purpose = `${format(specific[kind], named)}${format(purposeFocusCopy[locale], { fields: fieldNames })}`;
  const description = format(t.intro, named) + " " + format(t.structure, { fields: fieldNames, more });
  return {
    description,
    intro: format(t.intro, named),
    purpose,
    audience: format(specific.audience, named),
    structure: format(t.structure, { fields: fieldNames, more }) + (hasTable ? (locale === "ko" ? " 반복 입력 표와 합계 영역도 포함합니다." : locale === "en" ? " A repeating-entry table and totals are also included." : locale === "ru" ? ` ${t.tableNote ?? ""}` : "") : ""),
    steps: `${t.steps}${format(specific.stepFocus, { fields: focusFields })}`,
    tips: `${t.tips}${format(specific.tipFocus, { fields: focusFields })}`,
    source: t.source,
    caution: policy ? t.caution : (locale === "ko" ? "이 템플릿은 일반적인 기록 보조용입니다. 조직별 필수 양식이나 제출 기준이 있다면 해당 기준을 우선하세요." : t.caution),
    faq: [{ question: t.faq1, answer: t.faqA1 }, { question: t.faq2, answer: t.faqA2 }, { question: specific.faqFields, answer: format(specific.faqFieldsAnswer, { fields: fieldNames }) }],
    headings: sectionLabels[locale],
  };
}
