export function buildLibraryContent(locale: Locale, category: string) { const t = copy[locale]; return { intro: t.library, use: t.libraryUse, category: format(t.category, { category }), recent: recentLabels[locale] }; }
export function localizedCategoryDescription(locale: Locale, category: string) { return format(copy[locale].category, { category }); }

